solutionCode:
pub fn valor_da_compra(preco: i32, qtd: i32) -> i32 {
    preco * qtd
}

pub fn carrinho(preco1: i32, qtd1: i32, preco2: i32, qtd2: i32) -> String {
    const TAXA: i32 = 5;
    let mut total = valor_da_compra(preco1, qtd1);
    total = total + valor_da_compra(preco2, qtd2);
    total += TAXA;
    println!("carrinho fechado");
    format!("{qtd1} x {preco1} + {qtd2} x {preco2} + {TAXA} = {total}")
}

testsCode:
use desafio::valor_da_compra;
use desafio::carrinho;

#[test]
fn testa_a_compra_de_tres_por_quatro() {
    assert_eq!(valor_da_compra(4, 3), 12);
}

#[test]
fn testa_a_compra_de_dois_por_dez() {
    assert_eq!(valor_da_compra(2, 10), 20);
}

#[test]
fn testa_o_carrinho_da_primeira_feira() {
    assert_eq!(carrinho(4, 3, 2, 10), "3 x 4 + 10 x 2 + 5 = 37");
}

#[test]
fn testa_o_carrinho_da_segunda_feira() {
    assert_eq!(carrinho(1, 5, 1, 5), "5 x 1 + 5 x 1 + 5 = 15");
}
